def _baseline_agentic_trace_policy(self, signal):
    s = (signal or "").lower()
    # Heuristic: align tool hints with feedback signals (validate, search, inspect syntax)
    if "noisy transfer" in s or "cold" in s or "warm" in s or "held-out" in s:
        return (
            "tools: run_subset\n"
            "hint: validate a candidate on a small subset before accepting it; "
            "compare cold vs warm prior on held-out families.\n"
            "tools: trace_search\n"
            "hint: collect prior failures and family examples (from traces) before proposing updates."
        )
    if "syntax" in s or "artifact" in s or "inspect" in s:
        return (
            "tools: artifact_linter\n"
            "hint: inspect the saved artifact for syntax and ensure current_code reuse is consistent."
        )
    # Default: still incorporate feedback rather than only echoing it
    return (
        "tools: trace_search\n"
        "hint: look up prior failures and family examples; then propose only after targeted validation."
    )

